<script setup lang="ts">
import {computed,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {ImageApps} from './Apps/all';
const route=useRoute(),router=useRouter(),tab=ref('TextToImage');
watch(()=>route.query.tab,value=>{tab.value=ImageApps.some(app=>app.name===value)?String(value):'TextToImage';},{immediate:true});
const feature=computed(()=>ImageApps.find(app=>app.name===tab.value));
</script>
<template><div class="image-workspace"><nav class="feature-navigation" aria-label="图像工具"><p>图像创作</p><button v-for="app in ImageApps" :key="app.name" type="button" :aria-current="tab===app.name?'page':undefined" @click="router.push('/image?tab='+app.name)"><img :src="app.icon" alt=""/><span>{{app.title}}<small>{{app.description}}</small></span></button></nav><div class="feature-content"><component :is="feature?.component" :key="tab"/></div></div></template>
<style scoped>.image-workspace{display:flex;min-height:100%;background:var(--theme-app-bg);color:var(--theme-text-primary)}.feature-navigation{width:220px;flex-shrink:0;padding:24px 14px;border-right:1px solid var(--theme-border);background:var(--studio-sidebar)}.feature-navigation>p{font-size:12px;font-weight:600;color:var(--theme-text-muted);margin:0 12px 18px}.feature-navigation button{display:flex;align-items:flex-start;gap:12px;width:100%;padding:14px 12px;background:transparent;border:1px solid transparent;border-radius:9px;color:var(--theme-text-secondary);text-align:left;margin-bottom:6px;font-size:14px}.feature-navigation button[aria-current=page]{background:var(--theme-brand-soft);color:var(--theme-brand);border-color:var(--studio-accent-border)}.feature-navigation button:hover{background:var(--theme-panel-bg-muted)}.feature-navigation img{width:20px;height:20px}.feature-navigation small{display:block;font-size:12px;color:var(--theme-text-muted);line-height:1.6;margin-top:4px}.feature-content{flex:1;min-width:0;padding:8px}@media(max-width:800px){.image-workspace{flex-direction:column}.feature-navigation{display:flex;gap:8px;width:100%;padding:12px;border-right:0;border-bottom:1px solid var(--theme-border)}.feature-navigation>p,.feature-navigation small{display:none}.feature-navigation button{margin:0;width:auto;flex:1}.feature-content{padding:0}}</style>